CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE IF NOT EXISTS roles(id SMALLSERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
INSERT INTO roles(name) VALUES('user'),('admin') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email TEXT NOT NULL,username TEXT NOT NULL CHECK(length(username) BETWEEN 2 AND 40),password_hash TEXT NOT NULL,role_id SMALLINT NOT NULL REFERENCES roles(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS users_email_uq ON users(lower(email));
CREATE TABLE IF NOT EXISTS token_denylist(jti UUID PRIMARY KEY,expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS token_denylist_exp ON token_denylist(expires_at);
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS countries(id SERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,code TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS brands(id SERIAL PRIMARY KEY,name TEXT NOT NULL,country_id INT NOT NULL REFERENCES countries(id),category_id INT NOT NULL REFERENCES categories(id),description TEXT,logo_url TEXT,founded_year INT CHECK(founded_year BETWEEN 1000 AND 2100),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS brands_name_uq ON brands(lower(name));
CREATE INDEX IF NOT EXISTS brands_country ON brands(country_id);CREATE INDEX IF NOT EXISTS brands_category ON brands(category_id);
CREATE INDEX IF NOT EXISTS brands_name_trgm ON brands USING gin(name gin_trgm_ops);
CREATE TABLE IF NOT EXISTS brand_history(id SERIAL PRIMARY KEY,brand_id INT NOT NULL REFERENCES brands(id) ON DELETE CASCADE,year INT CHECK(year BETWEEN 1000 AND 2100),event TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS brand_history_brand ON brand_history(brand_id,year);
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,brand_id INT NOT NULL REFERENCES brands(id) ON DELETE CASCADE,category_id INT NOT NULL REFERENCES categories(id),country_id INT NOT NULL REFERENCES countries(id),name TEXT NOT NULL,description TEXT,history TEXT,abv NUMERIC(4,1) CHECK(abv>=0 AND abv<=100),abv_note TEXT,bottle_image_url TEXT,model_url TEXT,specs JSONB NOT NULL DEFAULT '{}',color INT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(brand_id,name));
CREATE INDEX IF NOT EXISTS products_brand ON products(brand_id);CREATE INDEX IF NOT EXISTS products_category ON products(category_id);CREATE INDEX IF NOT EXISTS products_country ON products(country_id);
CREATE INDEX IF NOT EXISTS products_name_trgm ON products USING gin(name gin_trgm_ops);
CREATE TABLE IF NOT EXISTS product_variants(id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id) ON DELETE CASCADE,name TEXT NOT NULL,abv NUMERIC(4,1) CHECK(abv>=0 AND abv<=100),size_ml INT CHECK(size_ml>0),UNIQUE(product_id,name));
CREATE TABLE IF NOT EXISTS assets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),kind TEXT NOT NULL CHECK(kind IN('bottle_model','bear_model','environment_model','texture','thumbnail','brand_logo')),product_id INT REFERENCES products(id) ON DELETE SET NULL,brand_id INT REFERENCES brands(id) ON DELETE SET NULL,original_name TEXT NOT NULL,stored_name TEXT NOT NULL UNIQUE,mime TEXT NOT NULL,size_bytes INT NOT NULL,url TEXT NOT NULL,uploaded_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS assets_product ON assets(product_id);
CREATE TABLE IF NOT EXISTS favorite_products(user_id UUID REFERENCES users(id) ON DELETE CASCADE,product_id INT REFERENCES products(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS favorite_brands(user_id UUID REFERENCES users(id) ON DELETE CASCADE,brand_id INT REFERENCES brands(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,brand_id));
CREATE TABLE IF NOT EXISTS recently_viewed(user_id UUID REFERENCES users(id) ON DELETE CASCADE,product_id INT REFERENCES products(id) ON DELETE CASCADE,viewed_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
CREATE INDEX IF NOT EXISTS recently_viewed_user ON recently_viewed(user_id,viewed_at DESC);
CREATE TABLE IF NOT EXISTS collections(id SERIAL PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 80),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,name));
CREATE TABLE IF NOT EXISTS collection_items(collection_id INT REFERENCES collections(id) ON DELETE CASCADE,product_id INT REFERENCES products(id) ON DELETE CASCADE,added_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(collection_id,product_id));
CREATE TABLE IF NOT EXISTS user_activity(id BIGSERIAL PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE SET NULL,session_id TEXT,type TEXT NOT NULL CHECK(type IN('visit','view','search','favorite','navigate')),entity_type TEXT,entity_id INT,meta JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS activity_type_time ON user_activity(type,created_at);CREATE INDEX IF NOT EXISTS activity_entity ON user_activity(entity_type,entity_id);
ALTER TABLE assets ADD COLUMN IF NOT EXISTS source_url TEXT,ADD COLUMN IF NOT EXISTS source_note TEXT,ADD COLUMN IF NOT EXISTS license TEXT NOT NULL DEFAULT 'unverified',ADD COLUMN IF NOT EXISTS attribution TEXT;
ALTER TABLE user_activity DROP CONSTRAINT IF EXISTS user_activity_type_check;
ALTER TABLE user_activity ADD CONSTRAINT user_activity_type_check CHECK(type IN('visit','view','search','favorite','navigate','cart_add','cart_remove','checkout','demo_confirm'));
CREATE TABLE IF NOT EXISTS product_prices(product_id INT PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE,price_minor INT NOT NULL CHECK(price_minor>=0 AND price_minor<=100000000),currency CHAR(3) NOT NULL DEFAULT 'INR',discount_bp INT NOT NULL DEFAULT 0 CHECK(discount_bp BETWEEN 0 AND 10000),status TEXT NOT NULL DEFAULT 'available' CHECK(status IN('available','limited','unavailable')),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS carts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE REFERENCES users(id) ON DELETE CASCADE,guest_token TEXT UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(user_id IS NOT NULL OR guest_token IS NOT NULL));
CREATE TABLE IF NOT EXISTS cart_items(id SERIAL PRIMARY KEY,cart_id UUID NOT NULL REFERENCES carts(id) ON DELETE CASCADE,product_id INT NOT NULL REFERENCES products(id) ON DELETE CASCADE,quantity INT NOT NULL CHECK(quantity BETWEEN 1 AND 20),added_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(cart_id,product_id));
CREATE TABLE IF NOT EXISTS demo_orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),reference TEXT NOT NULL UNIQUE,session_token TEXT NOT NULL UNIQUE,user_id UUID REFERENCES users(id) ON DELETE SET NULL,cart_id UUID REFERENCES carts(id) ON DELETE SET NULL,customer_name TEXT CHECK(length(customer_name)<=80),currency CHAR(3) NOT NULL,subtotal_minor INT NOT NULL,tax_minor INT NOT NULL,total_minor INT NOT NULL,tax_bp INT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','confirmed')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),expires_at TIMESTAMPTZ NOT NULL,scanned_at TIMESTAMPTZ,confirmed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS demo_orders_created ON demo_orders(created_at DESC);
CREATE TABLE IF NOT EXISTS demo_order_items(id SERIAL PRIMARY KEY,order_id UUID NOT NULL REFERENCES demo_orders(id) ON DELETE CASCADE,product_id INT REFERENCES products(id) ON DELETE SET NULL,brand TEXT NOT NULL,product_name TEXT NOT NULL,unit_minor INT NOT NULL,discount_bp INT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),line_minor INT NOT NULL);
